import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

fun <T, R> List<T>.mapChecked10890(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
sealed class Outcome10891 {
    data class Success(val payload: String) : Outcome10891()
    data object Failure : Outcome10891()
}

fun describe10891(outcome: Outcome10891): String = when (outcome) {
    is Outcome10891.Success -> outcome.payload
    Outcome10891.Failure -> "failed"
}
class Counter10892 {
    var current: Int by Delegates.observable(14) { _, _, new -> println(new) }

    suspend fun advance(): Int {
